doc.add_paragraph(
    '1. \u041e\u0431\u043c\u0435\u0436\u0438\u0442\u0438 \u043f\u0435\u0440\u0435\u0433\u043b\u044f\u0434 \u0441\u043e\u0446\u0456\u0430\u043b\u044c\u043d\u0438\u0445 \u043c\u0435\u0440\u0435\u0436 \u0434\u043e 20 \u0445\u0432\u0438\u043b\u0438\u043d \u043d\u0430 \u0434\u0435\u043d\u044c (\u0435\u043a\u043e\u043d\u043e\u043c\u0456\u044f \u0431\u043b\u0438\u0437\u044c\u043a\u043e 30 \u0445\u0432/\u0434\u0435\u043d\u044c).\n'
    '2. \u0412\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0432\u0430\u0442\u0438 \u0447\u0430\u0441 \u0443 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0456 \u0434\u043b\u044f \u043f\u0440\u043e\u0441\u043b\u0443\u0445\u043e\u0432\u0443\u0432\u0430\u043d\u043d\u044f \u043d\u0430\u0432\u0447\u0430\u043b\u044c\u043d\u0438\u0445 \u043f\u043e\u0434\u043a\u0430\u0441\u0442\u0456\u0432 \u0430\u0431\u043e \u0447\u0438\u0442\u0430\u043d\u043d\u044f \u0444\u0430\u0445\u043e\u0432\u043e\u0457 \u043b\u0456\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u0438.\n'
    '3. \u041f\u043b\u0430\u043d\u0443\u0432\u0430\u0442\u0438 \u043d\u0430\u0441\u0442\u0443\u043f\u043d\u0438\u0439 \u0434\u0435\u043d\u044c \u0443\u0432\u0435\u0447\u0435\u0440\u0456, \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u044e\u0447\u0438 \u043c\u0435\u0442\u043e\u0434 \u00ab\u0410\u041b\u041f\u0421\u00bb \u0430\u0431\u043e \u043c\u0430\u0442\u0440\u0438\u0446\u044e \u0415\u0439\u0437\u0435\u043d\u0445\u0430\u0443\u0435\u0440\u0430.\n'
    '4. \u0412\u043f\u0440\u043e\u0432\u0430\u0434\u0438\u0442\u0438 \u0442\u0435\u0445\u043d\u0456\u043a\u0443 Pomodoro (\u0440\u043e\u0431\u043e\u0442\u0430 25 \u0445\u0432 / \u043f\u0435\u0440\u0435\u0440\u0432\u0430 5 \u0445\u0432) \u0434\u043b\u044f \u0441\u0430\u043c\u043e\u0441\u0442\u0456\u0439\u043d\u043e\u0457 \u043f\u0456\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0438.\n'
    '5. \u0412\u0438\u0434\u0456\u043b\u0438\u0442\u0438 \u0444\u0456\u043a\u0441\u043e\u0432\u0430\u043d\u0438\u0439 \u0447\u0430\u0441 \u0434\u043b\u044f \u0444\u0456\u0437\u0438\u0447\u043d\u043e\u0457 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0456 \u0449\u043e\u0434\u043d\u044f (30\u201345 \u0445\u0432).\n'
    '6. \u0413\u0440\u0443\u043f\u0443\u0432\u0430\u0442\u0438 \u043e\u0434\u043d\u043e\u0442\u0438\u043f\u043d\u0456 \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f (\u0431\u0430\u0442\u0447\u0438\u043d\u0433): \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0456 \u043d\u0430 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f, \u043f\u043e\u0431\u0443\u0442\u043e\u0432\u0456 \u0441\u043f\u0440\u0430\u0432\u0438 \u0442\u043e\u0449\u043e.'
)

