    '\u041f\u0440\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0439 \u0445\u0440\u043e\u043d\u043e\u043c\u0435\u0442\u0440\u0430\u0436 \u043f\u043e\u043a\u0430\u0437\u0430\u0432, \u0449\u043e \u043d\u0430\u0432\u0447\u0430\u043b\u044c\u043d\u0430 \u0434\u0456\u044f\u043b\u044c\u043d\u0456\u0441\u0442\u044c \u0437\u0430\u0439\u043c\u0430\u0454 \u043b\u0438\u0448\u0435 \u0431\u043b\u0438\u0437\u044c\u043a\u043e 30% \u0434\u043e\u0431\u0438, '
    '\u043f\u0440\u0438 \u0446\u044c\u043e\u043c\u0443 \u043d\u0435 \u043c\u0435\u043d\u0448\u0435 3,5% \u0447\u0430\u0441\u0443 \u0432\u0442\u0440\u0430\u0447\u0430\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u0445\u0440\u043e\u043d\u043e\u0444\u0430\u0433\u0438 (\u043f\u043e\u0433\u043b\u0438\u043d\u0430\u0447\u0456 \u0447\u0430\u0441\u0443). '
    '\u0417\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u0446\u0435 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0431\u043b\u0438\u0437\u044c\u043a\u043e 6 \u0433\u043e\u0434\u0438\u043d \u0432\u0442\u0440\u0430\u0447\u0435\u043d\u043e\u0433\u043e \u0447\u0430\u0441\u0443, '
